let audioCtx;
        let oscillator;
        let gainNode;
        let analyser;
        let isPlaying = false;
        let animationId;
        function initAudio() {
            if (!audioCtx) {
                const AudioContext = window.AudioContext || window.webkitAudioContext;
                audioCtx = new AudioContext();
                gainNode = audioCtx.createGain();
                analyser = audioCtx.createAnalyser();
                gainNode.connect(analyser);
                analyser.connect(audioCtx.destination);
                analyser.fftSize = 2048;
                drawVisualizer();
            }
            if (audioCtx.state === 'suspended') {
                audioCtx.resume();
            }
        }
        function togglePlay() {
            initAudio();
            const btn = document.getElementById('play-btn');
            const icon = document.getElementById('play-icon');
            const text = document.getElementById('play-text');
            if (isPlaying) {
                stopTone();
                btn.classList.replace('bg-red-500', 'bg-cyan-500');
                btn.classList.remove('animate-pulse');
                icon.innerHTML = '<path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clip-rule="evenodd"></path>';
                text.innerText = "Start Tone";
                document.getElementById('match-result').classList.remove('hidden');
                window.scrollTo({ top: document.getElementById('match-result').offsetTop - 100, behavior: 'smooth' });
            } else {
                startTone();
                btn.classList.replace('bg-cyan-500', 'bg-red-500');
                btn.classList.add('animate-pulse');
                icon.innerHTML = '<path fill-rule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zM7 8a1 1 0 012 0v4a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v4a1 1 0 102 0V8a1 1 0 00-1-1z" clip-rule="evenodd"></path>';
                text.innerText = "Stop Signal";
                document.getElementById('match-result').classList.add('hidden');
            }
            isPlaying = !isPlaying;
        }
        function startTone() {
            oscillator = audioCtx.createOscillator();
            oscillator.type = 'sine';
            const freq = document.getElementById('freq-slider').value;
            const vol = document.getElementById('vol-slider').value;
            oscillator.frequency.value = freq;
            gainNode.gain.setValueAtTime(vol, audioCtx.currentTime);
            oscillator.connect(gainNode);
            oscillator.start();
        }
        function stopTone() {
            if (oscillator) {
                gainNode.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + 0.15);
                oscillator.stop(audioCtx.currentTime + 0.15);
                oscillator = null;
            }
        }
        function updateFreq(val) {
            document.getElementById('freq-display').innerText = val;
            if (oscillator) {
                oscillator.frequency.setTargetAtTime(val, audioCtx.currentTime, 0.05);
            }
            document.getElementById('match-val').innerText = val;
        }
        function nudgeFreq(amount) {
            const slider = document.getElementById('freq-slider');
            let val = parseInt(slider.value) + amount;
            val = Math.max(100, Math.min(14000, val));
            slider.value = val;
            updateFreq(val);
        }
        function updateVol(val) {
            document.getElementById('vol-display').innerText = Math.round(val * 200) + '%';
            if (gainNode) {
                gainNode.gain.setTargetAtTime(val, audioCtx.currentTime, 0.1);
            }
        }
        function saveMatch() {
            const freq = document.getElementById('freq-slider').value;
            // Human understandable confirm logic
            const status = document.createElement('div');
            status.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-cyan-600 text-white px-8 py-3 rounded-2xl font-black uppercase tracking-widest text-xs shadow-2xl z-[100] animate-bounce";
            status.innerText = `Archived: ${freq} Hz`;
            document.body.appendChild(status);
            setTimeout(() => status.remove(), 3000);
        }
        function drawVisualizer() {
            const canvas = document.getElementById("visualizer");
            const canvasCtx = canvas.getContext("2d");
            const bufferLength = analyser.frequencyBinCount;
            const dataArray = new Uint8Array(bufferLength);
            canvas.width = canvas.parentElement.offsetWidth;
            canvas.height = 140;
            function draw() {
                animationId = requestAnimationFrame(draw);
                analyser.getByteTimeDomainData(dataArray);
                canvasCtx.fillStyle = "rgb(15, 23, 42)";
                canvasCtx.fillRect(0, 0, canvas.width, canvas.height);
                canvasCtx.lineWidth = 3;
                canvasCtx.strokeStyle = "rgb(34, 211, 238)";
                canvasCtx.beginPath();
                const sliceWidth = canvas.width * 1.0 / bufferLength;
                let x = 0;
                for (let i = 0; i < bufferLength; i++) {
                    const v = dataArray[i] / 128.0;
                    const y = v * canvas.height / 2;
                    if (i === 0) {
                        canvasCtx.moveTo(x, y);
                    } else {
                        canvasCtx.lineTo(x, y);
                    }
                    x += sliceWidth;
                }
                canvasCtx.lineTo(canvas.width, canvas.height / 2);
                canvasCtx.stroke();
            }
            draw();
        }
